#!/bin/bash

# Notification helper
send_notify() {
    notify-send -u normal -i preferences-system "System Boost" "$1"
}

# 1. Sync file system writes immediately
# (Flushes pending I/O write operations to disk so desktop doesn't stutter on disk locks)
sync

# 2. Track freed cache
initial_avail=$(free -m | awk 'NR==2{print $7}')

# 3. Clean user-level bloated caches (Safe, non-destructive, zero password required)
# - Thumbnail caches (generated by file managers, image viewers)
rm -rf "$HOME/.cache/thumbnails"/* 2>/dev/null || true

# - Browser temporary disk caches (safe to remove, does NOT touch cookies, logins, or history)
rm -rf "$HOME/.cache/BraveSoftware/Brave-Browser/Default/Cache"/* 2>/dev/null || true
rm -rf "$HOME/.cache/BraveSoftware/Brave-Browser/Default/Code Cache"/* 2>/dev/null || true
rm -rf "$HOME/.cache/google-chrome/Default/Cache"/* 2>/dev/null || true
rm -rf "$HOME/.cache/mozilla/firefox/"*"/cache2"/* 2>/dev/null || true

# - Spotify media streaming data cache
rm -rf "$HOME/.cache/spotify/Data"/* 2>/dev/null || true

# - Old temp files in /tmp created by the current user (> 1 day old)
find /tmp -maxdepth 2 -user "$USER" -type f \( -name "satty_*" -o -name "tmp_*" \) -delete 2>/dev/null || true

# - Vacuum user systemd journals to free memory & disk
journalctl --user --vacuum-time=1d >/dev/null 2>&1 || true

# 4. If sudo is available without prompt, drop kernel pagecache / dentries / inodes
if sudo -n true 2>/dev/null; then
    sudo sh -c 'sync; echo 3 > /proc/sys/vm/drop_caches' 2>/dev/null
fi

final_avail=$(free -m | awk 'NR==2{print $7}')
diff=$(( final_avail - initial_avail ))
[ "$diff" -lt 0 ] && diff=0

send_notify "Cache cleared & memory refreshed!\nAvailable Memory: ${final_avail} MB"
echo "Freed cache. Available: ${final_avail} MB"
